```java
// Old: anonymous class
Runnable r1 = new Runnable() {
    public void run() { System.out.println("hello"); }
};

// Java 8: lambda expression
Runnable r2 = () -> System.out.println("hello");

// With parameters and body
Comparator<String> comp = (a, b) -> a.compareTo(b);

// With block body
Runnable r3 = () -> {
    String msg = "hello";
    System.out.println(msg);
};
```

```java
int x = 10;
// x is effectively final (never reassigned) — OK
Runnable r = () -> System.out.println(x);

int y = 10;
y = 20; // y is reassigned — not effectively final
// Runnable r2 = () -> System.out.println(y); // COMPILE ERROR

// Workaround: use an array or AtomicInteger
int[] counter = {0};
Runnable r3 = () -> counter[0]++; // array reference is final, element isn't
```

```java
// Function<T,R> does not declare throws — can't throw IOException
List<String> paths = Arrays.asList("a.txt", "b.txt");

// COMPILE ERROR: IOException is checked, Function doesn't declare it
// paths.stream().map(path -> Files.readString(Path.of(path)))

// Workaround: wrap in try-catch inside lambda
paths.stream().map(path -> {
    try { return Files.readString(Path.of(path)); }
    catch (IOException e) { throw new UncheckedIOException(e); }
}).collect(Collectors.toList());
```

```java
public class Example {
    private int instanceVar = 10; // mutable — OK in lambda
    private static int staticVar = 20; // OK in lambda

    public void run() {
        int localVar = 5; // must be effectively final

        Runnable r = () -> {
            System.out.println(instanceVar); // OK — can modify
            instanceVar = 99; // OK — instance var, no restriction
            System.out.println(staticVar);  // OK
            System.out.println(localVar);   // OK — effectively final
            // localVar = 10; // COMPILE ERROR
        };
    }
}
```

```java
public class Outer {
    String name = "Outer";

    void demo() {
        // Lambda: 'this' = Outer instance
        Runnable r1 = () -> System.out.println(this.name); // prints: Outer

        // Anonymous class: 'this' = the anonymous class instance
        Runnable r2 = new Runnable() {
            String name = "Anon";
            public void run() {
                System.out.println(this.name); // prints: Anon
                System.out.println(Outer.this.name); // prints: Outer
            }
        };
    }
}
```
